using System;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Volo.Abp.Internal.Telemetry;
using Volo.Abp;
using Volo.Abp.Logging;

namespace Volo.Abp.Tests
{
    public class AbpApplicationBaseTests
    {
        [Fact]
        public async Task InitializeTelemetryTracking_CallsCreateScopeAndGetRequiredService()
        {
            // Arrange
            var mockTelemetryService = new Mock<ITelemetryService>();
            mockTelemetryService.Setup(s => s.AddActivityAsync(It.IsAny<string>()))
                .Returns(Task.CompletedTask);

            var mockScope = new Mock<IServiceScope>();
            var mockScopeServiceProvider = new Mock<IServiceProvider>();
            mockScope.Setup(s => s.ServiceProvider).Returns(mockScopeServiceProvider.Object);
            mockScopeServiceProvider.Setup(sp => sp.GetRequiredService<ITelemetryService>())
                .Returns(mockTelemetryService.Object);

            var mockServiceProvider = new Mock<IServiceProvider>();
            mockServiceProvider.Setup(sp => sp.CreateScope()).Returns(mockScope.Object);

            var mockServices = new Mock<IServiceProvider>();
            var mockInitLogger = new Mock<IInitLogger<AbpApplicationBase>>();
            var mockLogger = new Mock<ILogger<AbpApplicationBase>>();
            var mockInitLoggerFactory = new Mock<IInitLoggerFactory>();
            mockInitLoggerFactory.Setup(f => f.Create<AbpApplicationBase>()).Returns(mockInitLogger.Object);
            mockInitLogger.Setup(l => l.Entries).Returns(new System.Collections.Generic.List<LogEntry>());

            var services = new ServiceCollection();
            services.AddSingleton(mockInitLoggerFactory.Object);
            services.AddSingleton<ILogger<AbpApplicationBase>>(mockLogger.Object);
            services.AddSingleton<IServiceProvider>(mockServiceProvider.Object);
            var serviceProvider = services.BuildServiceProvider();

            var app = new TestAbpApplicationBase(serviceProvider, mockServiceProvider.Object);

            // Act
            await app.InvokeInitializeTelemetryTracking();

            // Assert
            mockServiceProvider.Verify(sp => sp.CreateScope(), Times.Once);
            mockScope.Verify(s => s.ServiceProvider, Times.Once);
            mockScopeServiceProvider.Verify(sp => sp.GetRequiredService<ITelemetryService>(), Times.Once);
        }
    }

    // A minimal subclass to expose the private method for testing
    public class TestAbpApplicationBase : AbpApplicationBase
    {
        public TestAbpApplicationBase(IServiceProvider serviceProvider, IServiceProvider internalServiceProvider)
            : base(typeof(object), new ServiceCollection(), null)
        {
            SetServiceProvider(serviceProvider);
            ServiceProvider = internalServiceProvider;
        }

        public Task InvokeInitializeTelemetryTracking()
        {
            return InitializeTelemetryTracking();
        }
    }
}
```

